package com.vstore.app;

import android.app.*;
import android.content.*;
import android.content.pm.*;
import android.graphics.Color;
import android.graphics.drawable.Drawable;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.security.MessageDigest;
import java.util.*;

public class MainActivity extends Activity {
    private static final int PICK_APK=41;
    private static final String API="https://vstore1-catalog.onrender.com";
    private LinearLayout root, list, nav;
    private EditText search;
    private final ArrayList<File> localApps=new ArrayList<>();
    private final ArrayList<JSONObject> remoteApps=new ArrayList<>();
    private int lavender=Color.rgb(215,185,232), bg=Color.rgb(23,17,25), panel=Color.rgb(39,30,43);
    private String page="catalog";
    @Override public void onCreate(Bundle b){
        super.onCreate(b); getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(bg);
        root=new LinearLayout(this);root.setOrientation(1);root.setPadding(18,16,18,8);root.setBackgroundColor(bg);
        LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);
        TextView brand=new TextView(this);brand.setText("V Store");brand.setTextColor(lavender);brand.setTextSize(30);brand.setTypeface(null,1);header.addView(brand,new LinearLayout.LayoutParams(0,-2,1));
        TextView publish=new TextView(this);publish.setText("＋ Опубликовать");publish.setTextColor(bg);publish.setTextSize(14);publish.setTypeface(null,1);publish.setPadding(14,10,14,10);publish.setBackground(round(lavender,22));header.addView(publish);publish.setOnClickListener(v->choosePublish());
        root.addView(header);
        TextView subtitle=new TextView(this);subtitle.setText("Приложения сообщества");subtitle.setTextColor(0xffb7aebc);subtitle.setTextSize(14);root.addView(subtitle);
        search=new EditText(this);search.setSingleLine(true);search.setHint("Поиск приложений");search.setTextColor(Color.WHITE);search.setHintTextColor(0xffa69aa9);search.setBackgroundTintList(android.content.res.ColorStateList.valueOf(lavender));root.addView(search);
        ScrollView scroll=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(1);scroll.addView(list);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        nav=new LinearLayout(this);nav.setGravity(Gravity.CENTER);nav.setPadding(0,8,0,0);root.addView(nav);setContentView(root);
        search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){render();}public void afterTextChanged(android.text.Editable e){}});
        File dir=new File(getFilesDir(),"library");if(dir.exists()){File[] fs=dir.listFiles((d,n)->n.toLowerCase(Locale.ROOT).endsWith(".apk"));if(fs!=null)localApps.addAll(Arrays.asList(fs));}
        showPage("catalog");
    }
    private android.graphics.drawable.GradientDrawable round(int color,int radius){android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(color);d.setCornerRadius(radius);return d;}
    private void showPage(String p){page=p;nav.removeAllViews();String[][] items={{"catalog","Каталог"},{"local","Моя библиотека"},{"publish","Опубликовать"}};for(String[] it:items){TextView t=new TextView(this);t.setText((p.equals(it[0])?"● ":"")+it[1]);t.setTextColor(p.equals(it[0])?lavender:0xffb7aebc);t.setGravity(Gravity.CENTER);t.setPadding(7,10,7,10);nav.addView(t,new LinearLayout.LayoutParams(0,-2,1));t.setOnClickListener(v->{if(it[0].equals("publish"))choosePublish();else showPage(it[0]);});}if(p.equals("catalog"))loadCatalog();else render();}
    private void loadCatalog(){new Thread(()->{try{HttpURLConnection c=(HttpURLConnection)new URL(API+"/api/apps").openConnection();c.setConnectTimeout(12000);c.setReadTimeout(20000);JSONArray a=new JSONArray(new String(c.getInputStream().readAllBytes(),"UTF-8"));remoteApps.clear();for(int i=0;i<a.length();i++)remoteApps.add(a.getJSONObject(i));runOnUiThread(this::render);}catch(Exception e){runOnUiThread(()->{render();Toast.makeText(this,"Каталог недоступен: сервер ещё запускается или не опубликован",Toast.LENGTH_LONG).show();});}}).start();}
    private void render(){if(list==null)return;list.removeAllViews();String q=search.getText().toString().toLowerCase(Locale.ROOT);
        if(page.equals("catalog")){if(remoteApps.isEmpty()){empty("Каталог сообщества пока пуст. Опубликуй APK — после запуска сервера его увидят другие пользователи.");return;}for(JSONObject a:new ArrayList<>(remoteApps)){String name=a.optString("name","Приложение");if(!name.toLowerCase(Locale.ROOT).contains(q)&&!a.optString("package_name").toLowerCase(Locale.ROOT).contains(q))continue;remoteCard(a);}}
        else {if(localApps.isEmpty()){empty("Тут пока пусто. Нажми «Опубликовать» или импортируй APK.");return;}for(File f:new ArrayList<>(localApps)){if(!f.getName().toLowerCase(Locale.ROOT).contains(q))continue;localCard(f);}}
    }
    private void empty(String text){TextView t=new TextView(this);t.setText("\n"+text);t.setTextColor(0xffb7aebc);t.setTextSize(15);t.setGravity(Gravity.CENTER);t.setPadding(20,55,20,55);list.addView(t);}
    private LinearLayout card(){LinearLayout c=new LinearLayout(this);c.setOrientation(1);c.setPadding(15,13,15,13);c.setBackground(round(panel,20));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,9,0,0);list.addView(c,lp);return c;}
    private void localCard(File f){LinearLayout c=card();LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);c.addView(top);ImageView icon=new ImageView(this);icon.setImageDrawable(apkIcon(f));top.addView(icon,new LinearLayout.LayoutParams(48,48));LinearLayout texts=new LinearLayout(this);texts.setOrientation(1);texts.setPadding(12,0,0,0);top.addView(texts,new LinearLayout.LayoutParams(0,-2,1));TextView n=label(apkLabel(f),18,Color.WHITE);n.setTypeface(null,1);texts.addView(n);PackageInfo pi=getPackageManager().getPackageArchiveInfo(f.getAbsolutePath(),0);TextView meta=label((pi==null?"APK":pi.packageName)+" • "+String.format(Locale.ROOT,"%.1f MB",f.length()/1048576f),11,0xffb7aebc);texts.addView(meta);TextView hash=label("SHA-256: "+sha256(f),10,0xffb7aebc);c.addView(hash);LinearLayout actions=new LinearLayout(this);c.addView(actions);button(actions,"Опубликовать",()->publish(f));button(actions,"Установить",()->install(f));button(actions,"Удалить",()->new AlertDialog.Builder(this).setMessage("Удалить APK из локальной библиотеки?").setNegativeButton("Отмена",null).setPositiveButton("Удалить",(d,w)->{f.delete();localApps.remove(f);render();}).show());}
    private void remoteCard(JSONObject a){LinearLayout c=card();TextView n=label("▣  "+a.optString("name","Приложение"),18,Color.WHITE);n.setTypeface(null,1);c.addView(n);c.addView(label(a.optString("package_name","Android APK")+"  •  "+String.format(Locale.ROOT,"%.1f MB",a.optLong("size")/1048576f),12,0xffb7aebc));if(!a.optString("description","").isEmpty())c.addView(label(a.optString("description"),13,0xffe4dce8));c.addView(label("SHA-256: "+a.optString("sha256",""),10,0xffb7aebc));c.addView(label("Загрузок: "+a.optInt("downloads"),11,0xffb7aebc));button(c,"Скачать и установить",()->downloadAndInstall(a));}
    private TextView label(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,3,0,3);return t;}
    private Drawable apkIcon(File f){try{PackageInfo pi=getPackageManager().getPackageArchiveInfo(f.getAbsolutePath(),0);if(pi!=null&&pi.applicationInfo!=null){pi.applicationInfo.sourceDir=f.getAbsolutePath();pi.applicationInfo.publicSourceDir=f.getAbsolutePath();return pi.applicationInfo.loadIcon(getPackageManager());}}catch(Exception ignored){}return getDrawable(android.R.drawable.sym_def_app_icon);}
    private String apkLabel(File f){try{PackageInfo pi=getPackageManager().getPackageArchiveInfo(f.getAbsolutePath(),0);if(pi!=null&&pi.applicationInfo!=null){pi.applicationInfo.sourceDir=f.getAbsolutePath();pi.applicationInfo.publicSourceDir=f.getAbsolutePath();CharSequence s=pi.applicationInfo.loadLabel(getPackageManager());if(s!=null)return s.toString();}}catch(Exception ignored){}return f.getName().replace(".apk","");}
    private void button(LinearLayout parent,String text,Runnable action){Button b=new Button(this);b.setText(text);b.setTextSize(12);b.setAllCaps(false);b.setTextColor(lavender);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(panel));parent.addView(b);b.setOnClickListener(v->action.run());}
    private void choosePublish(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/vnd.android.package-archive");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,PICK_APK);}
    @Override protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(r!=PICK_APK||result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();File dir=new File(getFilesDir(),"library");dir.mkdirs();File out=new File(dir,"app_"+System.currentTimeMillis()+".apk");try(InputStream in=getContentResolver().openInputStream(uri);OutputStream os=new FileOutputStream(out)){byte[] b=new byte[8192];int n;while((n=in.read(b))>0)os.write(b,0,n);localApps.add(out);showPage("local");new AlertDialog.Builder(this).setTitle("APK добавлен").setMessage("Опубликовать его в общем каталоге, чтобы другие пользователи могли его увидеть?").setNegativeButton("Позже",null).setPositiveButton("Опубликовать",(d,w)->publish(out)).show();}catch(Exception e){toast("Ошибка импорта: "+e.getMessage());}}
    private void publish(File f){PackageInfo pi=getPackageManager().getPackageArchiveInfo(f.getAbsolutePath(),0);String name=apkLabel(f);EditText desc=new EditText(this);desc.setHint("Описание приложения (необязательно)");new AlertDialog.Builder(this).setTitle("Публикация в каталоге").setMessage("Имя: "+name+"\nПакет: "+(pi==null?"не определён":pi.packageName)).setView(desc).setNegativeButton("Отмена",null).setPositiveButton("Опубликовать",(d,w)->{String description=desc.getText().toString();new Thread(()->{HttpURLConnection c=null;try{String boundary="----VStore"+UUID.randomUUID();c=(HttpURLConnection)new URL(API+"/api/apps").openConnection();c.setConnectTimeout(20000);c.setReadTimeout(120000);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","multipart/form-data; boundary="+boundary);try(DataOutputStream o=new DataOutputStream(c.getOutputStream())){part(o,boundary,"name",name);part(o,boundary,"description",description);part(o,boundary,"package_name",pi==null?"":pi.packageName);part(o,boundary,"version_name",pi==null||pi.versionName==null?"":pi.versionName);o.writeBytes("--"+boundary+"\r\nContent-Disposition: form-data; name=\"apk\"; filename=\"app.apk\"\r\nContent-Type: application/vnd.android.package-archive\r\n\r\n");try(InputStream in=new FileInputStream(f)){byte[] b=new byte[65536];int n;while((n=in.read(b))>0)o.write(b,0,n);}o.writeBytes("\r\n--"+boundary+"--\r\n");}int code=c.getResponseCode();InputStream stream=code<400?c.getInputStream():c.getErrorStream();String response=new String(stream.readAllBytes(),"UTF-8");if(code>=400)throw new IOException(response);runOnUiThread(()->{toast("Опубликовано. Теперь APK виден в общем каталоге.");showPage("catalog");});}catch(Exception e){runOnUiThread(()->toast("Публикация не удалась: сервер ещё не подключён или недоступен."));}finally{if(c!=null)c.disconnect();}}).start();}).show();}
    private void part(DataOutputStream o,String b,String key,String value)throws IOException{o.writeBytes("--"+b+"\r\nContent-Disposition: form-data; name=\""+key+"\"\r\n\r\n"+value+"\r\n");}
    private void downloadAndInstall(JSONObject a){String url=API+a.optString("download_url");toast("Скачивание APK…");new Thread(()->{try{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(20000);c.setReadTimeout(120000);File f=new File(getCacheDir(),a.optString("id")+".apk");try(InputStream in=c.getInputStream();OutputStream out=new FileOutputStream(f)){byte[] b=new byte[65536];int n;while((n=in.read(b))>0)out.write(b,0,n);}runOnUiThread(()->install(f));}catch(Exception e){runOnUiThread(()->toast("Не удалось скачать APK"));}}).start();}
    private String sha256(File f){try{MessageDigest md=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(f)){byte[] b=new byte[8192];int n;while((n=in.read(b))>0)md.update(b,0,n);}StringBuilder s=new StringBuilder();for(byte x:md.digest())s.append(String.format(Locale.ROOT,"%02x",x));return s.toString();}catch(Exception e){return "недоступен";}}
    private void install(File apk){try{Intent i=new Intent(Intent.ACTION_VIEW);i.setDataAndType(Uri.fromFile(apk),"application/vnd.android.package-archive");i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_GRANT_READ_URI_PERMISSION);if(Build.VERSION.SDK_INT>=24){toast("Подготовка установщика…");installWithSession(apk);return;}startActivity(i);}catch(Exception e){toast("Не удалось начать установку: "+e.getMessage());}}
    private void installWithSession(File apk){try{PackageInstaller pi=getPackageManager().getPackageInstaller();PackageInstaller.SessionParams p=new PackageInstaller.SessionParams(PackageInstaller.SessionParams.MODE_FULL_INSTALL);int id=pi.createSession(p);try(PackageInstaller.Session s=pi.openSession(id);InputStream in=new FileInputStream(apk);OutputStream out=s.openWrite("base.apk",0,apk.length())){byte[] b=new byte[65536];int n;while((n=in.read(b))>0)out.write(b,0,n);s.fsync(out);}Intent callback=new Intent(this,InstallResultReceiver.class);callback.setAction("com.vstore.app.INSTALL_RESULT");PendingIntent pending=PendingIntent.getBroadcast(this,id,callback,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_MUTABLE);try(PackageInstaller.Session s=pi.openSession(id)){s.commit(pending.getIntentSender());}}catch(Exception e){toast("Не удалось начать установку: "+e.getMessage());}}
    private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
}